if(PHP_SAPI!=='cli')exit(1);ob_start();require_once __DIR__.'/../koneksi.php';require_once __DIR__.'/http_form_scope.php';spp_test_assert_database_target($koneksi);require_once __DIR__.'/../includes/legacy_operational_bank.php';require_once __DIR__.'/legacy_finance_support.php';
$fixture=json_decode(file_get_contents(dirname(getenv('SPP_TEST_ISOLATED_INSTANCE')).'/operational-fixture.json'),true);$actor=(int)$fixture['actor'];$batch=$fixture['job'];unit_set_context($koneksi,1);$_SESSION=['admin_id'=>$actor,'admin_role'=>'super_admin','active_unit_id'=>1];function opc_cash_digest(mysqli $db): string {$h=hash_init('sha256');foreach(['bayar','bayar_du','bayar_biaya_lain','transaksi_m','transaksi_k'] as $table)foreach(lf_rows($db,"SELECT * FROM $table ORDER BY id") as $row)hash_update($h,lf_json($row));foreach(lf_rows($db,'SELECT id,SPP_PERBULAN FROM siswa ORDER BY id') as $row)hash_update($h,lf_json($row));return hash_final($h);}$nativeBefore=opc_cash_digest($koneksi);
function opc_change(mysqli $db,int $actor,string $kind,array $record,array $patch): array {
    $input=['owner_id'=>$record['owner_id'],'date'=>$record['source_date'],'note'=>$record['note'],'reason'=>'Owned cancellation and identity correction proof.','preview_expires'=>time()+300,'cancelled'=>(bool)$record['cancelled']];if($kind==='payment'){$input['period']=$record['source_period'];$input['items']=is_string($record['items'])?json_decode($record['items'],true):$record['items'];}else{$input['incoming']=$record['incoming'];$input['outgoing']=$record['outgoing'];}$input=array_replace($input,$patch);$p=lop_correction_preview($db,$actor,1,$kind,(int)$record['id'],(int)$record['version'],$input);$input['confirmation']='SIMPAN KOREKSI';lop_correction_apply($db,$actor,1,$kind,(int)$record['id'],(int)$record['version'],$input,$p['digest'],bin2hex(random_bytes(32)));return lop_record($db,$kind,(int)$record['id']);
}
