$from=lf_one($koneksi,"SELECT * FROM legacy_op_owners WHERE batch_id=? AND source_identity='GK02'",[$batch]);$to=lf_one($koneksi,"SELECT * FROM legacy_op_owners WHERE batch_id=? AND source_identity='GK01'",[$batch]);$journal=lf_one($koneksi,"SELECT * FROM legacy_op_journals WHERE owner_id=? AND origin='legacy'",[$from['id']]);$before1=lf_one($koneksi,'SELECT opening,balance FROM legacy_op_accounts WHERE owner_id=?',[$from['id']]);$before2=lf_one($koneksi,'SELECT opening,balance FROM legacy_op_accounts WHERE owner_id=?',[$to['id']]);$journal=opc_change($koneksi,$actor,'journal',$journal,['owner_id'=>$to['id']]);lft_assert(lf_one($koneksi,'SELECT opening FROM legacy_op_accounts WHERE owner_id=?',[$from['id']])['opening']==='0.00','Transfer did not rebase source account');opc_change($koneksi,$actor,'journal',$journal,['owner_id'=>$from['id']]);lft_assert(lf_one($koneksi,'SELECT opening,balance FROM legacy_op_accounts WHERE owner_id=?',[$from['id']])===$before1&&lf_one($koneksi,'SELECT opening,balance FROM legacy_op_accounts WHERE owner_id=?',[$to['id']])===$before2,'Transfer/restore changed unrelated balances');lft_assert(opc_cash_digest($koneksi)===$nativeBefore,'Cancel/restore rewrote native cash or tariff');lop_check_result($koneksi,$batch);echo "PASS: payment/journal cancellation and restoration, both-account transfer, no new cash and no source tariff changes.\n";
